"""Find the field names an element category knows: those not listed in left_out.
usage: names.py CATEGORY... ; writes /tmp/loader-agent/names/<cat>.json"""
import sys, json, re, os, copy
sys.path.insert(0, '/tmp/loader-agent')
from lib import *

DOC = load('/tmp/loader-agent/corpus/c4.bimcraft')
NAMES = json.load(open('/tmp/loader-agent/names.json'))


def find(cat):
    for k, v in DOC['elements'].items():
        if v['category'] == cat:
            last = (k, v)
    return last


def attempt(eid, el):
    d = copy.deepcopy(DOC)
    d['elements'][eid] = el
    code, msg, saved = open_file(d, save=False)
    return code, msg


def left_of(msg):
    try:
        r = json.loads(msg)
    except Exception:
        return None
    return r.get('left_out', []), r.get('left_out_count', 0)


def discover(cat):
    eid, el = find(cat)
    present = list(el.keys())
    cands = [n for n in NAMES if n not in el]
    known_null_ok = []   # accept null
    known_errs = {}      # name -> error with null
    pending = cands
    # batches of 90
    i = 0
    while i < len(pending):
        batch = pending[i:i + 90]
        e = dict(el)
        for n in batch:
            e[n] = None
        code, msg = attempt(eid, e)
        if code == 0:
            lo, cnt = left_of(msg)
            assert cnt == len(lo), (cnt, len(lo))
            reported = set(p.split('/')[-1] for p in lo)
            for n in batch:
                if n not in reported:
                    known_null_ok.append(n)
            i += 90
        else:
            # find the first name in batch that errors, by bisection
            lo_, hi = 0, len(batch)
            while hi - lo_ > 1:
                mid = (lo_ + hi) // 2
                e = dict(el)
                for n in batch[lo_:mid]:
                    e[n] = None
                c2, m2 = attempt(eid, e)
                if c2 != 0:
                    hi = mid
                else:
                    lo_ = mid
            bad = batch[lo_]
            e = dict(el); e[bad] = None
            c2, m2 = attempt(eid, e)
            known_errs[bad] = m2
            pending = pending[:i] + [n for n in batch if n != bad] + pending[i + 90:]
    return {'present': present, 'null_ok': known_null_ok, 'null_err': known_errs}


