    for k, v in d['elements'].items():
        c = v['category']
        orders.setdefault(c, set()).add(tuple(v.keys()))
        for fk, fv in v.items():
            examples.setdefault(c, {}).setdefault(fk, fv)
    for g in d.get('detail_groups', {}).values():
        for m in g.get('members', []):
            e = m['element']
            orders.setdefault('member:' + e['category'], set()).add(tuple(e.keys()))


def merge(seqs):
    # topological merge
    nodes = []
    for s in seqs:
        for x in s:
            if x not in nodes:
                nodes.append(x)
    after = {n: set() for n in nodes}
    for s in seqs:
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                after[s[i]].add(s[j])
    out = []
    left = list(nodes)
    while left:
        for n in left:
            if not any(n in after[m] for m in left if m != n):
                out.append(n); left.remove(n); break
        else:
            out.append('CYCLE:' + ','.join(left)); break
    return out


json.dump({c: {k: v for k, v in ex.items()} for c, ex in examples.items()}, open('/tmp/loader-agent/examples.json', 'w'))
for c in sorted(orders):
    m = merge(sorted(orders[c]))
    known = None
    p = '/tmp/loader-agent/names/%s.json' % c
    extra = ''
    if os.path.exists(p):
        nm = json.load(open(p))
        known = set(nm['present']) | set(nm['null_ok']) | set(nm['null_err'])
        extra = ' | never seen: ' + ' '.join(sorted(known - set(m)))
    print(c, ':', ' '.join(m), extra)

