NAMES = json.load(open('/tmp/loader-agent/names.json'))
PROBES = [True, "zz", 5, -5, 1.5, [], {}, None]
NBP = 'open: x.bimcraft is not a BIMCraft project: '


def split(path):
    return [p.replace('~1', '/').replace('~0', '~') for p in path.split('/')] if path else []


def get(d, parts):
    for p in parts:
        d = d[int(p)] if isinstance(d, list) else d[p]
    return d


def put(d, parts, v):
    d = copy.deepcopy(d)
    x = d
    for p in parts[:-1]:
        x = x[int(p)] if isinstance(x, list) else x[p]
    last = parts[-1]
    if isinstance(x, list):
        x[int(last)] = v
    else:
        x[last] = v
    return d


def delete(d, parts):
    d = copy.deepcopy(d)
    x = d
    for p in parts[:-1]:
        x = x[int(p)] if isinstance(x, list) else x[p]
    if isinstance(x, list):
        del x[int(parts[-1])]
    else:
        x.pop(parts[-1], None)
    return d


def attempt(doc, save=False):
    code, msg, saved = open_file(doc, save=save)
    return code, msg, saved


def strip(msg):
    msg = msg.replace(NBP, 'NBP: ')
    return re.sub(r'^NBP: element \d+: ', 'NBP: EL: ', msg)


def walk(path, tag=None):
    parts = split(path)
    prefix = []
    sname = None
    i = 0
    out = []
    while i < 80:
        arr = ([tag] if tag else []) + prefix
        code, msg, _ = attempt(put(DOC, parts, arr))
        m = re.search(r'expected (struct \S+) with (\d+) elements', msg)
        if m and sname is None:
            sname = m.group(1)
        code2, msg2, _ = attempt(put(DOC, parts, arr + [None]))
        if 'elements in sequence' in msg2 or 'fewer elements in array' in msg2:
            print('END at', i, '(%s)' % strip(msg2))
            break
        req = bool(re.search(r'invalid length %d, expected struct' % i, msg))
        res = []
        valid = None; found = False
        for pr in PROBES + json.loads(os.environ.get('EXTRA', '[]')):
            c, mm, _ = attempt(put(DOC, parts, arr + [pr]))
            res.append((pr, strip(mm) if c else 'OK'))
            mj = re.search(r'invalid length (\d+), expected struct', mm)
            ok = c == 0 or (mj and int(mj.group(1)) > i) or (NBP not in mm)
            if ok and not found:
                valid = pr; found = True
        exps = sorted(set(re.search(r'expected (.*)$', m_).group(1) for _, m_ in res if re.search(r'expected (.*)$', m_) and 'invalid length' not in m_))
        print('[%d] %s  %s  valid=%s' % (i, 'REQ' if req else 'opt', ' | '.join(exps)[:200], json.dumps(valid)[:60] if found else 'NONE'))
        if os.environ.get('V'):
            for pr, mm in res:
                print('      %s -> %s' % (json.dumps(pr), mm[:200]))
        out.append({'i': i, 'req': req, 'exps': exps, 'res': res})
        if not found:
            print('stuck; prefix:', json.dumps(prefix)[:300])
            break
        prefix.append(valid)
        i += 1
    print('struct:', sname)
    return out


def left_of(msg):
    try:
        r = json.loads(msg)
    except Exception:
        return None
    return r.get('left_out', []), r.get('left_out_count', 0)


def names(path):
    parts = split(path)
    base = get(DOC, parts)
    cands = [n for n in NAMES + json.loads(os.environ.get('EXTRA_NAMES', '[]')) if n not in base]
    known_ok, known_err = [], {}
    i = 0
    pending = cands
    prefix = '/' + '/'.join(p.replace('~', '~0').replace('/', '~1') for p in parts) + '/'
    while i < len(pending):
        batch = pending[i:i + 90]
        e = dict(base)
        for n in batch:
            e[n] = None
        code, msg, _ = attempt(put(DOC, parts, e))
        if code == 0:
            lo, cnt = left_of(msg)
            rep = set(p[len(prefix):] for p in lo if p.startswith(prefix))
            for n in batch:
                if n.replace('~', '~0').replace('/', '~1') not in rep:
                    known_ok.append(n)
            i += 90
        else:
            lo_, hi = 0, len(batch)
            while hi - lo_ > 1:
                mid = (lo_ + hi) // 2
                e = dict(base)
                for n in batch[lo_:mid]:
                    e[n] = None
                c2, m2, _ = attempt(put(DOC, parts, e))
                if c2 != 0:
                    hi = mid
                else:
                    lo_ = mid
            bad = batch[lo_]
            e = dict(base); e[bad] = None
            c2, m2, _ = attempt(put(DOC, parts, e))
            known_err[bad] = strip(m2)
            pending = pending[:i] + [n for n in batch if n != bad] + pending[i + 90:]
    print('present:', list(base.keys()))
    print('null ok:', known_ok)
    for k, v in known_err.items():
        print('null err:', k, '->', v[:200])


SIGP = [True, "zz", 5, -5, 1.5, [], {}, None, "00000000-0000-4000-8000-000000000001", [1.0, 2.0], [[1.0, 2.0]], {"zz": 1}]


def sig(path, keys=None):
    parts = split(path)
    base = get(DOC, parts)
    keys = keys or list(base.keys())
    for n in keys:
        res = []
        for pr in SIGP:
            e = dict(base); e[n] = pr
            c, m, _ = attempt(put(DOC, parts, e))
            res.append((pr, 'OK' if c == 0 else strip(m)))
        e = dict(base); e.pop(n, None)
        c, m, saved = attempt(put(DOC, parts, e), save=True)
        absent = 'OK' if c == 0 else strip(m)
        if c == 0:
            try:
                sv = get(json.loads(saved), parts).get(n, '<omitted>')
            except Exception as ex:
                sv = '<?%s>' % ex
            absent = 'OK -> %s' % json.dumps(sv)[:100]
        exps = sorted(set(re.search(r'expected (.*)$', m_).group(1) for _, m_ in res if re.search(r'expected (.*)$', m_)))
        oks = [json.dumps(p) for p, m_ in res if m_ == 'OK']
        print('%-18s absent: %s' % (n, absent[:150]))
        print('%-18s exp: %s' % ('', ' / '.join(exps)[:300]))
        print('%-18s ok: %s' % ('', ' '.join(oks)[:200]))
        if os.environ.get('V'):
            for p, m_ in res:
                print('      %s -> %s' % (json.dumps(p), m_[:200]))


def trysave(path, js):
    parts = split(path)
    c, m, saved = attempt(put(DOC, parts, json.loads(js)), save=True)
    print(c, m[:1500])
    if saved:
        print(json.dumps(get(json.loads(saved), parts)))


if __name__ == '__main__':
    cmd = sys.argv[1]
    if cmd == 'walk':
        walk(sys.argv[2], sys.argv[3] if len(sys.argv) > 3 else None)
    elif cmd == 'names':
        names(sys.argv[2])
    elif cmd == 'sig':
        sig(sys.argv[2], sys.argv[3:] or None)
    elif cmd == 'try':
        trysave(sys.argv[2], sys.argv[3])

