"""Differential fuzzing of the loader: mutate a corpus file, open+save with both, compare.
usage: fuzz.py [--doc FILE] [--only CATEGORIES] [--sections] [--max N] [--seed S]"""
import sys, json, os, copy, random, re, argparse, hashlib
from multiprocessing import Pool
sys.path.insert(0, '/tmp/loader-agent')
from lib import *

ap = argparse.ArgumentParser()
ap.add_argument('--doc', default='/tmp/loader-agent/corpus/c7.bimcraft')
ap.add_argument('--only', default='')
ap.add_argument('--sections', default='')
ap.add_argument('--max', type=int, default=0)
ap.add_argument('--seed', type=int, default=1)
ap.add_argument('--jobs', type=int, default=8)
ap.add_argument('--depth', type=int, default=6)
ap.add_argument('--show', type=int, default=1)
ap.add_argument('--kinds', default='')
args = ap.parse_args()

DOC = load(args.doc)
G0 = '00000000-0000-4000-8000-0000000000aa'
PROBES = [('null', None), ('true', True), ('false', False), ('zero', 0), ('neg', -1), ('float', 1.5),
          ('str', 'zz'), ('empty_str', ''), ('arr', []), ('obj', {}), ('arr2', [1, 2]), ('arr3', [1, 2, 3]),
          ('nested', [[1, 2]]), ('objk', {'zz': 1}), ('guid', G0), ('big', 1e20), ('int', 7)]


def paths(v, pre, depth):
    """Every (path, value) inside v."""
    yield pre, v
    if depth <= 0:
        return
    if isinstance(v, dict):
        for k, x in v.items():
            yield from paths(x, pre + [k], depth - 1)
    elif isinstance(v, list):
        for i, x in enumerate(v[:3]):
            yield from paths(x, pre + [i], depth - 1)


def setp(d, p, val, delete=False):
    x = d
    for k in p[:-1]:
        x = x[k]
    if delete:
        if isinstance(x, dict):
            x.pop(p[-1], None)
        else:
            del x[p[-1]]
    else:
        x[p[-1]] = val


def pattern(p):
    """A path's shape: element ids by category, indices as #."""
    out = []
    for i, k in enumerate(p):
        if isinstance(k, int):
            out.append('#')
        elif i == 1 and p[0] == 'elements':
            out.append(DOC['elements'][k]['category'])
        elif len(p) > 1 and p[0] not in ('elements',) and i == 1:
            out.append('*')
        else:
            out.append(str(k))
    return '/'.join(out)


def mutations():
    muts = []
    roots = []
    only = set(args.only.split(',')) if args.only else None
    if not args.sections:
        for eid, e in DOC['elements'].items():
            if only and e['category'] not in only:
                continue
            roots.append(['elements', eid])
    else:
        for s in args.sections.split(','):
            if s in DOC:
                roots.append([s])
    seen = set()
    for r in roots:
        v = DOC
        for k in r:
            v = v[k]
        for p, x in paths(v, r, args.depth):
            pat = pattern(p)
            if len(p) > len(r):
                key = (pat, 'del')
                muts.append((p, 'del', None, pat))
            for name, val in PROBES:
                muts.append((p, name, val, pat))
            if isinstance(x, dict):
                muts.append((p + ['zz_unknown'], 'addkey', 1, pat + '/+'))
            if isinstance(x, str) and GUID.fullmatch(x):
                muts.append((p, 'upper', x.upper(), pat))
                muts.append((p, 'braces', '{' + x + '}', pat))
    if args.kinds:
        ks = set(args.kinds.split(','))
        muts = [m for m in muts if m[1] in ks]
    random.Random(args.seed).shuffle(muts)
    # one of each (pattern, kind) first, then the rest
    first, rest, seen = [], [], set()
    for m in muts:
        k = (m[3], m[1])
        if k in seen:
            rest.append(m)
        else:
            seen.add(k)
            first.append(m)
    muts = first + rest
    if args.max:
        muts = muts[:args.max]
    return muts


def strip_notes(s):
    lines = s.split('\n')
    if lines and lines[0].startswith('{'):
        try:
            r = json.loads(lines[0])
            r.pop('cads_not_reloaded', None)
            r.pop('links_not_loaded', None)
            lines[0] = json.dumps(r, sort_keys=True)
        except Exception:
            pass
    return '\n'.join(lines)


def one(m):
    p, kind, val, pat = m
    d = copy.deepcopy(DOC)
    try:
        if kind == 'del':
            setp(d, p, None, delete=True)
        else:
            setp(d, p, val)
    except Exception as e:
        return None
    text = json.dumps(d, indent=1)
    args_ = ['run', 'x.bimcraft', '--save', 'y.bimcraft']
    o = run(args_, {'x.bimcraft': text}, exe=ORIG)
    mm = run(args_, {'x.bimcraft': text}, exe=MINE)
    a = (o[0], strip_notes(norm(o[1])), norm(o[2]), norm(o[3].get('y.bimcraft', b'').decode('utf-8', 'replace')))
    b = (mm[0], strip_notes(norm(mm[1])), norm(mm[2]), norm(mm[3].get('y.bimcraft', b'').decode('utf-8', 'replace')))
    if a == b:
        return None
    # describe
    desc = []
    if a[0] != b[0] or a[2] != b[2]:
        desc.append('orig[%d] %s' % (a[0], a[2].strip()[:300]))
        desc.append('mine[%d] %s' % (b[0], b[2].strip()[:300]))
    if a[1] != b[1]:
        desc.append('stdout orig: ' + a[1][:300])
        desc.append('stdout mine: ' + b[1][:300])
    if a[3] != b[3] and a[0] == 0 and b[0] == 0:
        import difflib
        dl = [l for l in difflib.unified_diff(a[3].splitlines(), b[3].splitlines(), lineterm='', n=1)][2:14]
        desc.extend(dl)
    return (pat, kind, json.dumps(val), '/'.join(map(str, p)), desc)


if __name__ == '__main__':
    muts = mutations()
    print('mutations:', len(muts), file=sys.stderr)
    groups = {}
    with Pool(args.jobs) as pool:
        for r in pool.imap_unordered(one, muts, chunksize=4):
            if r is None:
                continue
            key = (r[0], r[1])
            groups.setdefault(key, []).append(r)
    for key in sorted(groups):
        rs = groups[key]
        print('=== %s [%s] x%d' % (key[0], key[1], len(rs)))
        for r in rs[:args.show]:
            print('   at %s = %s' % (r[3], r[2]))
            for l in r[4]:
                print('      ' + l[:400])
    print('groups:', len(groups), file=sys.stderr)

