"""Top-level sections: what is written when one is left out, or given empty."""
import sys, json, copy
sys.path.insert(0, '/tmp/loader-agent')
from lib import *

DOC = load(sys.argv[1] if len(sys.argv) > 1 else '/tmp/loader-agent/corpus/c7.bimcraft')
keys = sys.argv[2:] or list(DOC.keys())


def show(v):
    s = json.dumps(v)
    return s if len(s) < 150 else s[:150] + '...(%d)' % len(s)


for k in keys:
    if k in ('elements', 'library'):
        continue
    res = {}
    for label, mut in [('absent', lambda d: d.pop(k, None)), ('{}', lambda d: d.__setitem__(k, {})), ('[]', lambda d: d.__setitem__(k, [])), ('null', lambda d: d.__setitem__(k, None))]:
        d = copy.deepcopy(DOC)
        mut(d)
        code, msg, saved = open_file(d)
        if saved:
            s = json.loads(saved)
            res[label] = show(s[k]) if k in s else '<omitted>'
            if label == 'absent' and k in s and s[k] == DOC.get(k):
                res[label] = '<same as input>'
        else:
            res[label] = 'ERR ' + msg.replace('open: x.bimcraft is not a BIMCraft project: ', 'NBP: ')[:150]
    print(k)
    for a, b in res.items():
        print('    %-7s %s' % (a, b))

