1	//! Phases, phase filters and design options: `phase`, `phase_filter`, `option`.
2	//!
3	//! The file keeps `phases` (names, in order), `phase_filters` (name: how each status shows),
4	//! `phase_overrides` (status: override, fill patterns by GUID) and `option_sets` (name: its
5	//! options and its primary's GUID), each written only where it differs from what an English
6	//! project starts with. The library names every phase (`phase`), filter (`phase-filter`), set
7	//! (`option-set`) and option (`design-option`, `Set: Option`); what refers to one holds its GUID:
8	//! an element's `Phase Created`, `Phase Demolished` and `Design Option` (in `params`), a view's or
9	//! a template's `graphics` (`phase`, `phase_filter`, `options` {set: option}), and the rules of
10	//! view filters and schedules that name one. What this session makes things in (`now`) is the
11	//! session's, kept by name.
12	
13	use super::common::*;
14	use crate::json::{Map, Value};
15	use crate::project::Project;
16	use crate::session::Session;
17	use std::collections::BTreeSet;
18	
19	pub const DEFAULT_PHASES: [&str; 2] = ["Existing", "New Construction"];
20	pub const STATUSES: [&str; 4] = ["new", "existing", "demolished", "temporary"];
21	const SHOWS: [&str; 3] = ["by-category", "overridden", "not-displayed"];
22	const CREATED: &str = "Phase Created";
23	const DEMOLISHED: &str = "Phase Demolished";
24	const OPTION: &str = "Design Option";
25	
26	const NAME_RULE: &str = "a name is 1 to 256 characters, with nothing before or after it but letters, digits and the like";
27	
28	/// The categories whose elements hold a phase of their own (doors and windows follow their wall).
29	const PHASED: &[&str] = &[
30	    "wall",
31	    "floor",
32	    "ceiling",
33	    "room",
34	    "column",
35	    "structuralcolumn",
36	    "footing",
37	    "beam",
38	    "stripfooting",
39	    "pipe",
40	    "duct",
41	    "conduit",
42	    "cabletray",
43	    "wire",
44	    "downconductor",
45	    "groundconductor",
46	    "cable",
47	    "stair",
48	    "ramp",
49	    "railing",
50	    "roof",
51	    "mass",
52	    "component",
53	];
54	
55	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
56	    match cid {
57	        "phase" => cmd_phase(s, p),
58	        "phase_filter" => cmd_phase_filter(s, p),
59	        "option" => cmd_option(s, p),
60	        _ => Err(format!("{}: not supported here", cid)),
61	    }
62	}
63	
64	// ---------------------------------------------------------------- defaults
65	
66	fn default_filters() -> Map {
67	    let f = |n: &str, e: &str, d: &str, t: &str| jobj! {"new" => n, "existing" => e, "demolished" => d, "temporary" => t};
68	    let mut m = Map::new();
69	    m.insert("Show All", f("by-category", "by-category", "by-category", "by-category"));
70	    m.insert("Show Complete", f("by-category", "by-category", "not-displayed", "by-category"));
71	    m.insert("Show New", f("by-category", "not-displayed", "not-displayed", "not-displayed"));
72	    m.insert("Show Previous + Demolished", f("not-displayed", "by-category", "overridden", "not-displayed"));
73	    m.insert("Show Previous + New", f("by-category", "overridden", "not-displayed", "by-category"));
74	    m
75	}
76	
77	fn default_overrides() -> Map {
78	    let red = || jobj! {"color" => Value::Arr(vec![Value::u(200), Value::u(40), Value::u(30)]), "dash" => "dashed"};
79	    let mut m = Map::new();
80	    m.insert("existing", jobj! {"halftone" => true});
81	    m.insert("demolished", jobj! {"projection" => red(), "cut" => red()});
82	    m
83	}
84	
85	// ---------------------------------------------------------------- the sections
86	
87	pub fn phases(pr: &Project) -> Vec<String> {
88	    match pr.get("phases").and_then(|v| v.as_arr()) {
89	        Some(a) => a.iter().map(|x| x.as_str().map(|s| s.to_string()).unwrap_or_else(|| x.to_compact())).collect(),
90	        None => DEFAULT_PHASES.iter().map(|s| s.to_string()).collect(),
91	    }
92	}
93	
94	fn set_phases(pr: &mut Project, ph: &[String]) {
95	    if ph.len() == 2 && ph[0] == DEFAULT_PHASES[0] && ph[1] == DEFAULT_PHASES[1] {
96	        pr.remove_top("phases");
97	    } else {
98	        pr.insert_top("phases", Value::Arr(ph.iter().map(|x| Value::s(x)).collect()));
99	    }
100	}
101	
102	/// The phase filters, each with its four statuses (by category where the file says none).
103	pub fn filters(pr: &Project) -> Map {
104	    match pr.get("phase_filters").and_then(|v| v.as_obj()) {
105	        Some(m) => {
106	            let mut out = Map::new();
107	            for (k, v) in &m.items {
108	                let mut f = Map::new();
109	                for st in STATUSES {
110	                    f.insert(st, v.get(st).cloned().unwrap_or_else(|| Value::s("by-category")));
111	                }
112	                out.insert(k, Value::Obj(f));
113	            }
114	            out
115	        }
116	        None => default_filters(),
117	    }
118	}
119	
120	fn set_filters(pr: &mut Project, mut f: Map) {
121	    f.sort();
122	    if f == default_filters() {
123	        pr.remove_top("phase_filters");
124	    } else {
125	        pr.insert_top("phase_filters", Value::Obj(f));
126	    }
127	}
