192	fn option_value_name(pr: &Project, set_name: &str, raw: &str) -> String {
193	    let full = name_of_guid(pr, "design-option", raw).unwrap_or_else(|| raw.to_string());
194	    if let Some(rest) = full.strip_prefix(&format!("{}: ", set_name)) {
195	        return rest.to_string();
