208	/// A name a command is given: text, trimmed, 1 to 256 characters.
209	fn name_of(v: &Value, cmd: &str, key: &str) -> R<String> {
210	    if let Value::Str(s) = v {
211	        let t = s.trim();
212	        let n = t.chars().count();
213	        if n >= 1 && n <= 256 {
214	            return Ok(t.to_string());
215	        }
216	    }
217	    Err(format!("{}: `{}` is a name of 1 to 256 characters, not {}", cmd, key, v.to_compact()))
218	}
