304	fn sorted_items(m: &Map) -> Vec<(String, Value)> {
305	    Value::Obj(m.clone()).sorted().as_obj().map(|m| m.items.clone()).unwrap_or_default()
306	}
307	
308	fn de_bool(v: &Value) -> R<bool> {
309	    match v {
310	        Value::Bool(b) => Ok(*b),
311	        _ => Err(format!("invalid type: {}, expected a boolean", v.kind_name())),
312	    }
313	}
314	
315	fn de_u8(v: &Value) -> R<u64> {
316	    use crate::json::Num;
317	    match v {
318	        Value::Num(Num::U(u)) if *u <= 255 => Ok(*u),
319	        Value::Num(Num::U(u)) => Err(format!("invalid value: integer `{}`, expected u8", u)),
320	        Value::Num(Num::I(i)) => Err(format!("invalid value: integer `{}`, expected u8", i)),
321	        _ => Err(format!("invalid type: {}, expected u8", v.kind_name())),
322	    }
323	}
324	
325	fn de_colour(v: &Value) -> R<[u8; 3]> {
326	    color_of(v).ok_or_else(|| format!("{} isn't a colour: [r, g, b], each 0 to 255, or \"#rrggbb\"", v.to_compact()))
327	}
328	
329	fn de_rgb_array(v: &Value) -> R<[u8; 3]> {
330	    let a = match v {
331	        Value::Arr(a) => a,
332	        _ => return Err(format!("invalid type: {}, expected an array of length 3", v.kind_name())),
333	    };
334	    let mut out = [0u8; 3];
335	    for i in 0..3 {
336	        match a.get(i) {
337	            Some(x) => out[i] = de_u8(x)? as u8,
338	            None => return Err(format!("invalid length {}, expected an array of length 3", i)),
339	        }
340	    }
341	    if a.len() > 3 {
342	        return Err(format!("invalid length {}, expected fewer elements in array", a.len()));
343	    }
344	    Ok(out)
345	}
