347	/// A key in a JSON pointer.
348	fn ptr(k: &str) -> String {
349	    k.replace('~', "~0").replace('/', "~1")
350	}
351	
352	/// A field a struct doesn't know: refused, or (reading a file) left out and listed.
353	fn unknown(left: &mut Option<&mut Vec<String>>, path: &str, k: &str, msg: String) -> R<()> {
354	    match left {
355	        Some(l) => {
356	            l.push(format!("{}/{}", path, ptr(k)));
357	            Ok(())
358	        }
359	        None => Err(msg),
360	    }
361	}
362	
363	fn de_fill(v: &Value, mut left: Option<&mut Vec<String>>, path: &str) -> R<PFill> {
364	    let m = match v {
365	        Value::Obj(m) => m,
366	        _ => return Err(format!("invalid type: {}, expected struct PatternFill", v.kind_name())),
367	    };
368	    let mut f = PFill::default();
369	    for (k, x) in sorted_items(m) {
370	        match k.as_str() {
371	            "pattern" => {
372	                f.pattern = match &x {
373	                    Value::Null => None,
374	                    Value::Str(s) => Some(s.clone()),
375	                    _ => return Err(format!("invalid type: {}, expected a string", x.kind_name())),
376	                }
377	            }
378	            "color" => f.color = de_rgb_array(&x)?,
379	            _ => unknown(&mut left, path, &k, format!("unknown field `{}`, expected `pattern` or `color`", k))?,
380	        }
381	    }
382	    Ok(f)
383	}
384	
385	fn de_style(v: &Value, mut left: Option<&mut Vec<String>>, path: &str) -> R<Style> {
386	    let m = match v {
387	        Value::Obj(m) => m,
388	        _ => return Err(format!("invalid type: {}, expected struct Style", v.kind_name())),
389	    };
390	    let mut st = Style::default();
391	    for (k, x) in sorted_items(m) {
392	        let sub = format!("{}/{}", path, ptr(&k));
393	        match k.as_str() {
394	            "color" => st.color = Some(de_colour(&x)?),
395	            "weight" => {
396	                let w = f64_of(&x)?;
397	                st.weight = Some(pen_of(w).ok_or_else(|| {
398	                    format!("a line weight is a pen, a whole number from 0 (a hairline) to 16, not {}", disp(w))
399	                })?);
400	            }
401	            "dash" => {
402	                st.dash = Some(match &x {
403	                    Value::Str(s) if ["solid", "dashed", "dotted"].contains(&s.as_str()) => s.clone(),
404	                    Value::Str(s) => {
405	                        return Err(format!("unknown variant `{}`, expected one of `solid`, `dashed`, `dotted`", s))
406	                    }
407	                    _ => return Err(format!("invalid type: {}, expected string or map", x.kind_name())),
408	                })
409	            }
410	            "fill" => st.fill = Some(de_colour(&x)?),
411	            "foreground" => st.foreground = Some(de_fill(&x, left.as_deref_mut(), &sub)?),
412	            "background" => st.background = Some(de_fill(&x, left.as_deref_mut(), &sub)?),
413	            _ => unknown(
414	                &mut left,
415	                path,
416	                &k,
417	                format!(
418	                    "unknown field `{}`, expected one of `color`, `weight`, `dash`, `fill`, `foreground`, `background`",
419	                    k
420	                ),
421	            )?,
422	        }
423	    }
424	    Ok(st)
425	}
