427	fn de_override(v: &Value, mut left: Option<&mut Vec<String>>, path: &str) -> R<Ovr> {
428	    let m = match v {
429	        Value::Obj(m) => m,
430	        _ => return Err(format!("invalid type: {}, expected struct Override", v.kind_name())),
431	    };
432	    let mut o = Ovr::default();
433	    for (k, x) in sorted_items(m) {
434	        let sub = format!("{}/{}", path, ptr(&k));
435	        match k.as_str() {
436	            "hidden" => o.hidden = de_bool(&x)?,
437	            "projection" => o.projection = Some(de_style(&x, left.as_deref_mut(), &sub)?),
438	            "cut" => o.cut = Some(de_style(&x, left.as_deref_mut(), &sub)?),
439	            "halftone" => o.halftone = de_bool(&x)?,
440	            "transparency" => o.transparency = de_u8(&x)?,
441	            "shown" => o.shown = de_bool(&x)?,
442	            _ => unknown(
443	                &mut left,
444	                path,
445	                &k,
446	                format!(
447	                    "unknown field `{}`, expected one of `hidden`, `projection`, `cut`, `halftone`, `transparency`, `shown`",
448	                    k
449	                ),
450	            )?,
451	        }
452	    }
453	    Ok(o)
454	}
