456	/// A pattern layer as the file holds it (`names`: the pattern by name, else by GUID).
457	fn fill_value(pr: &Project, f: &PFill, names: bool) -> Value {
458	    let pat = match &f.pattern {
459	        None => Value::Null,
460	        Some(n) => {
461	            if names {
462	                Value::s(n)
463	            } else {
464	                Value::s(&pr.lib_guid("fill-pattern", n).unwrap_or_else(|| n.clone()))
