struct Member {
    id: u64 = 0
    guid: Option<Ref>
    element: MemberElement
}

struct DetailGroupType {
    members: Vec<Member>
}

struct Preset {
    kind: String
    params: Map<Any>
}

# ---------------------------------------------------------------- electrical

struct Voltage {
    nominal: f64
    min: f64
    max: f64
}

struct DistributionSystem {
    phases: u8
    wires: u8
    l_l: Option<String> ?none
