use std::collections::HashMap;

type R<T> = Result<T, String>;

/// The elements by GUID, for what points at them.
pub struct Index<'a> {
    pr: &'a Project,
    by_guid: HashMap<String, u64>,
}

impl<'a> Index<'a> {
    pub fn new(pr: &'a Project) -> Index<'a> {
        let mut by_guid = HashMap::new();
        for (id, e) in &pr.elements {
            if let Some(g) = e.get("guid").and_then(|x| x.as_str()) {
                by_guid.entry(g.to_string()).or_insert(*id);
            }
        }
        Index { pr, by_guid }
    }
    fn cat(&self, id: u64) -> &str {
        self.pr.elements.get(&id).and_then(|e| e.get("category")).and_then(|c| c.as_str()).unwrap_or("")
    }
}

/// What a reference names: the element (by GUID, or by its id), how it reads in a message, and
/// whether it names it by its id.
struct Target {
    id: Option<u64>,
    shown: String,
    by_id: bool,
}

fn target(ix: &Index, v: &Value) -> Option<Target> {
    match v {
        Value::Str(s) => match ix.by_guid.get(s) {
            Some(id) => Some(Target { id: Some(*id), shown: id.to_string(), by_id: false }),
            None => Some(Target { id: None, shown: s.clone(), by_id: false }),
        },
        Value::Num(Num::U(n)) => {
            let found = ix.pr.elements.contains_key(n);
            Some(Target { id: if found { Some(*n) } else { None }, shown: n.to_string(), by_id: found })
        }
        Value::Null => None,
        other => Some(Target { id: None, shown: other.to_compact(), by_id: false }),
    }
}

/// The names of a section's entries, as the original lists them.
fn names(pr: &Project, path: &[&str]) -> Vec<String> {
    let mut v = pr.get(path[0]);
    for p in &path[1..] {
        v = v.and_then(|x| x.get(p));
    }
    v.and_then(|x| x.as_obj()).map(|m| m.keys().cloned().collect()).unwrap_or_default()
}

/// The name a library reference holds: its library entry's (by GUID, of that kind), else as it is.
fn lib_name(pr: &Project, kind: &str, v: &Value) -> Option<String> {
    let s = v.as_str()?;
    for (_, e) in &pr.library {
        if e.get("kind").and_then(|k| k.as_str()) == Some(kind) && e.get("guid").and_then(|g| g.as_str()) == Some(s) {
            return e.get("name").and_then(|n| n.as_str()).map(|n| n.to_string());
        }
    }
    None
}

fn type_section(cat: &str) -> Option<Vec<&'static str>> {
    Some(match cat {
        "wall" => vec!["types", "wall"],
        "floor" => vec!["types", "floor"],
        "ceiling" => vec!["types", "ceiling"],
        "roof" => vec!["types", "roof"],
        "column" => vec!["types", "column"],
        "structuralcolumn" => vec!["types", "structural_column"],
        "footing" => vec!["types", "footing"],
        "railing" => vec!["types", "railing"],
        "door" => vec!["types", "door"],
        "window" => vec!["types", "window"],
        _ => return None,
    })
}

const RUNS: &[&str] = &[
    "beam", "stripfooting", "pipe", "duct", "conduit", "cabletray", "wire", "downconductor", "groundconductor", "cable",
];

fn there_are(list: &[String]) -> String {
    list.join(", ")
}

/// The element's type (or family and type) names one the project has.
fn check_type(pr: &Project, id: u64, cat: &str, e: &Value) -> R<()> {
    let t = match e.get("type") {
        Some(t) => t,
        None => return Ok(()),
    };
    let fam = e.get("family").filter(|f| !f.is_null());
    if cat == "component" || (matches!(cat, "door" | "window") && fam.is_some()) {
        let f = fam.cloned().unwrap_or(Value::Null);
        let fname = match lib_name(pr, "family", &f) {
            Some(n) => n,
            None => {
                let all: Vec<String> = match cat {
                    "door" | "window" => pr
                        .section("families")
                        .map(|m| {
                            m.iter()
                                .filter(|(_, v)| v.get("category").and_then(|c| c.as_str()) == Some(cat))
                                .map(|(k, _)| k.clone())
                                .collect()
                        })
                        .unwrap_or_default(),
                    _ => names(pr, &["families"]),
                };
                return Err(format!("{} {}: family `{}` doesn't exist (there are: {})", cat, id, shown(&f), there_are(&all)));
            }
        };
        if lib_name(pr, "family-type", t).is_none() {
            let types = names(pr, &["families", &fname, "types"]);
            return Err(format!("{} {}: type `{}` doesn't exist (there are: {})", cat, id, shown(t), there_are(&types)));
        }
        return Ok(());
    }
    let (kind, path) = if RUNS.contains(&cat) {
        (format!("type:{}", cat), vec!["types".to_string(), "runs".to_string(), cat.to_string()])
    } else if let Some(p) = type_section(cat) {
        (format!("type:{}", cat), p.iter().map(|s| s.to_string()).collect())
    } else {
        return Ok(());
    };
    if lib_name(pr, &kind, t).is_none() {
        let p: Vec<&str> = path.iter().map(|s| s.as_str()).collect();
        return Err(format!("{} {}: type `{}` doesn't exist (there are: {})", cat, id, shown(t), there_are(&names(pr, &p))));
    }
    Ok(())
}

fn shown(v: &Value) -> String {
    match v {
        Value::Str(s) => s.clone(),
        other => other.to_compact(),
    }
}

/// A library thing an element names by kind: refused with the original's words when it isn't one.
fn check_named(pr: &Project, id: u64, cat: &str, e: &Value, key: &str, kind: &str, what: &str, section: &str, list: bool) -> R<()> {
    let v = match e.get(key) {
        Some(v) if !v.is_null() => v,
        _ => return Ok(()),
    };
    if lib_name(pr, kind, v).is_none() {
        let tail = if list { format!(" (there are: {})", there_are(&names(pr, &[section]))) } else { String::new() };
        return Err(format!("{} {}: there's no {} `{}`{}", cat, id, what, shown(v), tail));
    }
    Ok(())
}

fn is_view(cat: &str, with_sheet: bool) -> bool {
    matches!(cat, "level" | "planview" | "section" | "elevation") || (with_sheet && cat == "sheet")
}

/// One element's references, checked as the original checks them; the first of its id references
/// (it reports those last) kept in `by_id`.
fn element(ix: &Index, id: u64, e: &Value, by_id: &mut Option<u64>) -> R<()> {
    let pr = ix.pr;
    let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
    let mut note = |t: &Target| {
        if t.by_id && by_id.is_none() {
            *by_id = t.id;
        }
    };
    check_type(pr, id, cat, e)?;
    // its level and its top level
    for key in ["level", "top_level"] {
        if let Some(v) = e.get(key) {
            if matches!(cat, "planview" | "level") && key == "top_level" {
                continue;
            }
            if let Some(t) = target(ix, v) {
                match t.id {
                    Some(n) if ix.cat(n) == "level" => note(&t),
                    _ => return Err(format!("{} {}: level {} doesn't exist", cat, id, t.shown)),
                }
            }
        }
    }
    match cat {
        "door" | "window" => {
            if let Some(t) = e.get("host").and_then(|v| target(ix, v)) {
                match t.id {
                    Some(n) if ix.cat(n) == "wall" => note(&t),
                    _ => return Err(format!("{} {}: host wall {} doesn't exist", cat, id, t.shown)),
                }
            }
        }
        "text" | "line" | "region" | "detailgroup" | "repeatingdetail" | "spot" => {
            if let Some(t) = e.get("view").and_then(|v| target(ix, v)) {
                let sheet_ok = cat != "spot";
                match t.id {
                    None => return Err(format!("{} {}: view {} doesn't exist", cat, id, t.shown)),
                    Some(n) if !is_view(ix.cat(n), sheet_ok) => {
                        let tail = if sheet_ok { "a plan, a section, an elevation or a sheet" } else { "a plan, a section, an elevation" };
                        return Err(format!("{} {}: {} {} isn't {}", cat, id, ix.cat(n), n, tail));
                    }
                    Some(_) => note(&t),
                }
            }
        }
        "dimension3d" => {
            if let Some(t) = e.get("view").and_then(|v| target(ix, v)) {
                match t.id {
                    Some(n) if ix.cat(n) == "view3d" => note(&t),
                    _ => return Err(format!("{} {}: view {} isn't a 3D view", cat, id, t.shown)),
                }
            }
        }
        "viewport" => {
            if let Some(t) = e.get("sheet").and_then(|v| target(ix, v)) {
                match t.id {
                    Some(n) if ix.cat(n) == "sheet" => note(&t),
                    Some(n) => return Err(format!("{} {}: {} {} isn't a sheet", cat, id, ix.cat(n), n)),
                    None => return Err(format!("{} {}: element {} isn't a sheet", cat, id, t.shown)),
                }
            }
            if let Some(t) = e.get("view").and_then(|v| target(ix, v)) {
                let ok = |c: &str| matches!(c, "level" | "planview" | "section" | "elevation" | "schedule" | "view3d");
                match t.id {
                    Some(n) if ok(ix.cat(n)) => note(&t),
                    Some(n) => {
                        return Err(format!(
                            "{} {}: {} {} isn't a plan, a section, an elevation, a schedule or a 3D view",
                            cat,
                            id,
                            ix.cat(n),
                            n
                        ))
                    }
                    None => {
                        return Err(format!(
                            "{} {}: element {} isn't a plan, a section, an elevation, a schedule or a 3D view",
                            cat, id, t.shown
                        ))
                    }
                }
            }
        }
        "railing" => {
            if let Some(t) = e.get("host").and_then(|v| target(ix, v)) {
                match t.id {
                    Some(n) if matches!(ix.cat(n), "stair" | "ramp") => note(&t),
                    _ => return Err(format!("{} {}: host {} isn't a stair or a ramp", cat, id, t.shown)),
                }
            }
        }
        "rebar" => {
            if let Some(t) = e.get("host").and_then(|v| target(ix, v)) {
                match t.id {
                    None => return Err(format!("{} {}: host {} doesn't exist", cat, id, t.shown)),
                    Some(n) if !matches!(ix.cat(n), "beam" | "column" | "structuralcolumn" | "footing" | "floor") => {
                        return Err(format!(
                            "{} {}: {} {} is no host for bars; a beam, a column, a footing or a floor is",
                            cat,
                            id,
                            ix.cat(n),
                            n
                        ))
                    }
                    Some(_) => note(&t),
                }
            }
        }
        "dimension" => {
            if let Some(Value::Arr(refs)) = e.get("refs") {
                for r in refs {
                    if let Some(t) = r.get("id").and_then(|v| target(ix, v)) {
                        match t.id {
                            None => return Err(format!("{} {}: element {} doesn't exist", cat, id, t.shown)),
                            Some(_) => note(&t),
                        }
                    }
                }
            }
        }
        "tag" => {
            if let Some(t) = e.get("host").and_then(|v| target(ix, v)) {
                match t.id {
                    None => return Err(format!("{} {}: element {} doesn't exist", cat, id, t.shown)),
                    Some(_) => note(&t),
                }
            }
        }
        _ => {}
    }
    match cat {
        "text" => check_named(pr, id, cat, e, "type", "text-type", "text type", "text_types", true)?,
        "dimension" | "dimension3d" => check_named(pr, id, cat, e, "type", "dimension-type", "dimension type", "dimension_types", true)?,
        "line" => check_named(pr, id, cat, e, "style", "line-style", "line style", "line_styles", true)?,
        "region" => {
            check_named(pr, id, cat, e, "type", "filled-region-type", "filled region type", "region_types", true)?;
            check_named(pr, id, cat, e, "line_style", "line-style", "line style", "line_styles", false)?;
        }
        "detailgroup" | "repeatingdetail" => {
            check_named(pr, id, cat, e, "type", "detail-group", "detail group", "detail_groups", true)?
        }
        "cadimport" => {
            if let Some(v) = e.get("cad") {
                if lib_name(pr, "cad", v).is_none() {
                    return Err(format!("{} {}: the project holds no CAD drawing named `{}`", cat, id, shown(v)));
                }
            }
        }
        _ => {}
    }
    Ok(())
}

/// Every element's references, in id order.
pub fn check(pr: &Project) -> R<()> {
    let ix = Index::new(pr);
    for (id, e) in &pr.elements {
        let mut by_id = None;
        element(&ix, *id, e, &mut by_id)?;
        if let Some(n) = by_id {
            let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
            return Err(format!("{} {} points at element {} by its id, not its GUID", cat, id, n));
        }
    }
    Ok(())
}

