/// The phases, in their order (an English project's where the file says none).
fn phases(pr: &Project) -> Vec<String> {
    crate::styles::phasing::phases(pr)
}

/// What a view's graphics name: its template, phase, phase filter, design options, filters,
/// linework styles, the elements it overrides and the fill patterns of its overrides.
fn graphics(ix: &Index, id: u64, cat: &str, g: &Value) -> R<()> {
    let pr = ix.pr;
    let who = format!("{} {}", cat, id);
    let lib_missing = |kind: &str, v: &Value| lib_name(pr, kind, v).is_none();
    if let Some(t) = g.get("template").filter(|v| !v.is_null()) {
        if lib_missing("view-template", t) {
            return Err(format!("{}: there's no view template `{}` (there are: {})", who, shown(t), there_are(&names(pr, &["view_templates"]))));
        }
    }
    if let Some(p) = g.get("phase").filter(|v| !v.is_null()) {
        if lib_missing("phase", p) {
            return Err(format!("{}: there's no phase `{}` (there are: {})", who, shown(p), there_are(&phases(pr))));
        }
    }
    if let Some(f) = g.get("phase_filter").filter(|v| !v.is_null()) {
        if lib_missing("phase-filter", f) {
            let filters: Vec<String> = crate::styles::phasing::filters(pr).keys().cloned().collect();
            return Err(format!("{}: there's no phase filter `{}` (there are: {})", who, shown(f), there_are(&filters)));
        }
    }
    if let Some(Value::Obj(opts)) = g.get("options") {
        for (set, opt) in opts.iter() {
            let set_v = Value::s(set);
            let set_name = match lib_name(pr, "option-set", &set_v) {
                Some(n) => n,
                None => {
                    return Err(format!(
                        "{}: there's no design option set `{}` (there are: {})",
                        who,
                        set,
                        there_are(&names(pr, &["option_sets"]))
                    ))
                }
            };
            if !opt.is_null() && lib_missing("design-option", opt) {
                let options: Vec<String> = pr
                    .section("option_sets")
                    .and_then(|m| m.get(&set_name))
                    .and_then(|s| s.get("options"))
                    .and_then(|o| o.as_arr())
                    .map(|a| a.iter().map(|x| shown(x)).collect())
                    .unwrap_or_default();
                return Err(format!(
                    "{}: design option set `{}` has no option `{}` (there are: {})",
                    who,
                    set_name,
                    shown(opt),
                    there_are(&options)
                ));
            }
        }
    }
    if let Some(Value::Arr(fs)) = g.get("filters") {
        for f in fs {
            if let Some(v) = f.get("filter") {
                if lib_missing("view-filter", v) {
                    return Err(format!("{}: there's no view filter `{}` (there are: {})", who, shown(v), there_are(&names(pr, &["view_filters"]))));
                }
            }
        }
    }
    if let Some(Value::Arr(ls)) = g.get("linework") {
        for (i, l) in ls.iter().enumerate() {
            if let Some(v) = l.get("style").filter(|v| !v.is_null()) {
                if lib_missing("line-style", v) {
                    return Err(format!(
