/// The curve a raw line's fields make, written as the original writes it.
fn curve(full: &Map, out: &mut Map) -> R<()> {
    let put = |out: &mut Map, k: &str| {
        if let Some(v) = some(full, k) {
            out.insert(k, v.clone());
        }
    };
    if some(full, "start").is_some() && some(full, "end").is_some() {
        put(out, "start");
        put(out, "end");
        put(out, "arc");
        put(out, "through");
    } else if some(full, "points").is_some() {
        put(out, "points");
        // arcs all nought are straight segments: none
        let curved = match some(full, "arcs") {
            Some(Value::Arr(a)) => a.iter().any(|x| x.as_f64() != Some(0.0)),
            _ => false,
        };
        if curved {
            put(out, "arcs");
        }
        if full.get("closed") == Some(&Value::Bool(true)) {
            out.insert("closed", Value::Bool(true));
        }
    } else if some(full, "centre").is_some() && some(full, "radius").is_some() {
        put(out, "centre");
        put(out, "radius");
    } else if some(full, "centre").is_some() && some(full, "radii").is_some() {
        put(out, "centre");
        put(out, "radii");
        put(out, "angle");
        put(out, "span");
    } else if some(full, "control").is_some() {
        put(out, "control");
        put(out, "knots");
    } else if some(full, "fit").is_some() {
        put(out, "fit");
        put(out, "start_tangent");
        put(out, "end_tangent");
    } else {
        return Err(LINE_FORMS.to_string());
    }
    Ok(())
}

