/// The lowest id the library and the parts of the model hold (a part's `id`: a layer's, a form's,
/// a sketch line's…), elements' aside.
pub fn lowest_id(library: &BTreeMap<u64, Value>, doc: &Map, elements: &BTreeMap<u64, Value>) -> u64 {
    let mut low = u64::MAX;
    if let Some(k) = library.keys().next() {
        low = *k;
    }
    super::ids::each_part(doc, elements, &mut |p: &mut Value| {
        if let Some(n) = p.get("id").and_then(|x| x.as_u64()) {
            if n != 0 && n < low {
                low = n;
            }
        }
    });
    if low == u64::MAX {
        1_000_000
    } else {
        low
    }
}

