/// The numbers an element holds are ones the model can use (within a million km), as the
/// original checks them, each named as it names it.
fn numbers(id: u64, cat: &str, e: &Value) -> R<()> {
    let max = crate::commands::params::MAX_MM;
    let bad = |label: &str, x: f64| -> R<()> {
        if x.is_finite() && x.abs() <= max {
            Ok(())
        } else {
            Err(format!("{} {} {}: {} is not a usable number", cat, id, label, x))
        }
    };
    let num = |k: &str, label: &str| -> R<()> {
        match e.get(k).and_then(|v| v.as_f64()) {
            Some(x) => bad(label, x),
            None => Ok(()),
        }
    };
    let pt = |v: Option<&Value>, lx: &str, ly: &str| -> R<()> {
        if let Some(Value::Arr(a)) = v {
            if let Some(x) = a.first().and_then(|x| x.as_f64()) {
                bad(lx, x)?;
            }
            if let Some(y) = a.get(1).and_then(|y| y.as_f64()) {
                bad(ly, y)?;
            }
        }
        Ok(())
    };
    let pt3 = |v: Option<&Value>, l: &str| -> R<()> {
        if let Some(Value::Arr(a)) = v {
            for (i, x) in a.iter().enumerate() {
                if let Some(x) = x.as_f64() {
                    let axis = ["x", "y", "z"].get(i).copied().unwrap_or("z");
                    bad(&format!("{} {}", l, axis).trim().to_string(), x)?;
                }
            }
        }
        Ok(())
    };
    let pts = |v: Option<&Value>, lx: &str, ly: &str| -> R<()> {
        if let Some(Value::Arr(a)) = v {
            for p in a {
                pt(Some(p), lx, ly)?;
            }
        }
        Ok(())
    };
    let no_top = e.get("top_level").map(|t| t.is_null()).unwrap_or(true);
    match cat {
        "wall" => {
            pt(e.get("start"), "x", "y")?;
            pt(e.get("end"), "x", "y")?;
            if no_top {
                num("height", "height")?;
            }
            num("base_offset", "base_offset")?;
            num("top_offset", "top_offset")?;
            num("arc", "arc")?;
        }
        "column" | "structuralcolumn" | "footing" => {
            pt(e.get("at"), "x", "y")?;
            num("angle", "angle")?;
            if no_top {
                num("height", "height")?;
            }
            num("base_offset", "base_offset")?;
        }
        "beam" | "stripfooting" | "pipe" | "duct" | "conduit" | "cabletray" | "wire" | "downconductor" | "groundconductor"
        | "cable" => {
            pt(e.get("start"), "start x", "start y")?;
            pt(e.get("end"), "end x", "end y")?;
            num("offset", "offset")?;
            num("end_offset", "end_offset")?;
        }
        "cadimport" => {
            pt(e.get("at"), "at x", "at y")?;
            num("angle", "angle")?;
        }
        "floor" | "ceiling" => {
