"""Schema exploration of element structs against the original."""
import sys, json, re, os, copy
sys.path.insert(0, '/tmp/loader-agent')
from lib import *

CORPUS = '/tmp/loader-agent/corpus/c4.bimcraft'
DOC = load(CORPUS)
PROBES = [True, "zz", 5, -5, 1.5, [], {}, None]


def canon_elements():
    seen = {}
    for k, v in DOC['elements'].items():
        seen.setdefault(v['category'], []).append((k, v))
    return seen


def el_attempt(cat, arr):
    text = json.dumps({"elements": {"100000": [cat] + arr}})
    code, msg, saved = open_file(text, save=False)
    return msg.replace('open: x.bimcraft is not a BIMCraft project: ', '')


def passes(msg, i):
    if not msg.startswith('element 100000: '):
        return True
    m = re.match(r'element 100000: invalid length (\d+), expected', msg)
    return bool(m and int(m.group(1)) > i and 'elements in sequence' not in msg)


def seq_walk(cat, cands):
    """Returns a list of positions: {i, without, probes: {probe: msg}, valid}."""
    prefix = []
    out = []
    i = 0
    while i < 80:
        without = el_attempt(cat, prefix)
        if 'elements in sequence' in without or 'fewer elements' in without or 'elements in sequence' in el_attempt(cat, prefix + [None]):
            break
        pos = {'i': i, 'without': without, 'probes': {}}
        for pr in PROBES:
            pos['probes'][json.dumps(pr)] = el_attempt(cat, prefix + [pr])
        valid = None; found = False
        for pr in PROBES:
            if passes(pos['probes'][json.dumps(pr)], i):
                valid = pr; found = True; break
        if not found:
            for c in cands:
                if passes(el_attempt(cat, prefix + [c]), i):
                    valid = c; found = True; break
        if not found:
            pos['stuck'] = True
            out.append(pos)
            break
        pos['valid'] = valid
        out.append(pos)
        prefix.append(valid)
        i += 1
    return out

