        if self.peek() == c:
            self.i += 1
            return True
        return False

    def expect(self, c):
        if not self.eat(c):
            raise ValueError('expected %r at %r' % (c, self.s[self.i:self.i + 40]))

    def word(self):
        self.ws()
        st = self.i
        while self.i < len(self.s) and (self.s[self.i].isalnum() or self.s[self.i] == '_'):
            self.i += 1
        if st == self.i:
            raise ValueError('expected a word at %r' % self.s[self.i:self.i + 40])
        return self.s[st:self.i]

    def token(self):
        self.ws()
        st = self.i
        while self.i < len(self.s) and not (self.s[self.i].isspace() or self.s[self.i] in '(}'):
            self.i += 1
        return self.s[st:self.i]

    def quoted(self):
        self.ws()
        self.expect('"')
        st = self.i
        while self.s[self.i] != '"':
            self.i += 1
        w = self.s[st:self.i]
        self.i += 1
        return w

    def json(self):
        self.ws()
        v, n = json.JSONDecoder().raw_decode(self.s, self.i)
        self.i = n
        return v

    def ty(self):
        if self.eat('['):
            t = self.ty()
            self.expect(';')
            n = int(self.word())
            self.expect(']')
            return ('arr', t, n)
        if self.eat('('):
            ts = [self.ty()]
            while self.eat(','):
                ts.append(self.ty())
            self.expect(')')
            return ('tup', ts)
        w = self.word()

        def one():
            self.expect('<')
            t = self.ty()
            self.expect('>')
            return t
        prim = {'f64': ('f64',), 'f32': ('f32',), 'bool': ('bool',), 'String': ('str',), 'u8': ('u', 8),
                'u16': ('u', 16), 'u32': ('u', 32), 'u64': ('u', 64), 'usize': ('u', 0), 'i8': ('i', 8),
                'i16': ('i', 16), 'i32': ('i', 32), 'i64': ('i', 64), 'Ref': ('ref',), 'Any': ('any',)}
        if w in prim:
            return prim[w]
        if w in ('Option', 'Some', 'Vec', 'Map', 'RefMap'):
            return (w.lower(), one())
        if w == 'EnumMap':
            self.expect('<')
            e = self.word()
            self.expect(',')
            t = self.ty()
            self.expect('>')
            return ('enummap', e, t)
        return ('named', w)


def parse_all():
    defs = {}
    for text in schema_texts():
        lx = Lx(text)
        while lx.peek() is not None:
            kw = lx.word()
            if kw == 'struct':
                name = lx.word()
                display = name
                if lx.peek() == '"':
                    display = lx.quoted()
                hook = None
                if lx.eat('@'):
                    hook = lx.word()
                lx.expect('{')
                fields = []
                while not lx.eat('}'):
                    fname = lx.word()
                    lx.expect(':')
                    t = lx.ty()
                    f = {'name': fname, 'ty': t, 'default': None, 'has_default': t[0] in ('option', 'some'),
                         'skip': 'never', 'hidden': False}
                    while True:
                        c = lx.peek()
                        if c == '=':
                            lx.i += 1
                            f['default'] = lx.json()
                            f['has_default'] = True
                        elif c == '?':
                            lx.i += 1
                            w = lx.word()
                            if w == 'eq':
                                f['skip'] = ('eq', lx.json())
                            elif w == 'never':
                                f['hidden'] = True
                            else:
                                f['skip'] = w
                        elif c == '~':
                            lx.i += 1
                            lx.word()
                        else:
                            break
                    fields.append(f)
                defs[name] = {'kind': 'struct', 'display': display, 'fields': fields, 'tuple': False, 'hook': hook}
            elif kw == 'tuple':
                name = lx.word()
                t = lx.ty()
                defs[name] = {'kind': 'struct', 'display': name, 'tuple': True, 'hook': None,
                              'fields': [{'name': str(i), 'ty': x, 'default': None, 'has_default': False,
                                          'skip': 'never', 'hidden': False} for i, x in enumerate(t[1])]}
            elif kw == 'enum':
                name = lx.word()
                lx.expect('{')
                vs = []
                while not lx.eat('}'):
                    w = lx.quoted() if lx.peek() == '"' else lx.token()
                    n, _, out = w.partition('>')
                    data = None
                    if lx.i < len(lx.s) and lx.s[lx.i] == '(':
                        lx.i += 1
                        data = lx.ty()
                        lx.expect(')')
                    vs.append({'name': n, 'out': out or n, 'data': data})
                defs[name] = {'kind': 'enum', 'variants': vs}
            elif kw == 'untagged':
                name = lx.word()
                lx.expect('=')
                ts = [lx.ty()]
                while lx.eat('|'):
                    ts.append(lx.ty())
                defs[name] = {'kind': 'untagged', 'types': ts}
            elif kw == 'alias':
                name = lx.word()
                lx.expect('=')
                defs[name] = {'kind': 'alias', 'ty': lx.ty()}
            else:
                raise ValueError('keyword ' + kw)
    for c in ['LibKind', 'Colour', 'Pen', 'Weight', 'MemberElement']:
        defs[c] = {'kind': 'custom'}
    return defs


