def instances(doc):
    """{struct name: [path, ...]} for every struct value in doc (type-directed)."""
    out = {}

    def walk(v, t, p):
        k = t[0]
        if k in ('option', 'some'):
            if v is not None:
                walk(v, t[1], p)
        elif k == 'vec':
            if isinstance(v, list):
                for i, x in enumerate(v):
                    walk(x, t[1], p + [i])
        elif k == 'arr':
            if isinstance(v, list):
                for i, x in enumerate(v):
                    walk(x, t[1], p + [i])
        elif k == 'tup':
            if isinstance(v, list):
                for i, (x, tt) in enumerate(zip(v, t[1])):
                    walk(x, tt, p + [i])
        elif k in ('map', 'refmap', 'enummap'):
            if isinstance(v, dict):
                for kk, x in v.items():
                    walk(x, t[-1], p + [kk])
        elif k == 'named':
            d = DEFS[t[1]]
            if d['kind'] == 'struct':
                out.setdefault(t[1], []).append(p)
                if d['tuple']:
                    if isinstance(v, list):
                        for i, (x, f) in enumerate(zip(v, d['fields'])):
                            walk(x, f['ty'], p + [i])
                elif isinstance(v, dict):
                    for f in d['fields']:
                        if f['name'] in v:
                            walk(v[f['name']], f['ty'], p + [f['name']])
            elif d['kind'] == 'enum':
                if isinstance(v, dict) and len(v) == 1:
                    (kk, x), = v.items()
                    for var in d['variants']:
                        if var['name'] == kk and var['data']:
                            walk(x, var['data'], p + [kk])
            elif d['kind'] == 'alias':
                walk(v, d['ty'], p)
    for k, t in MODEL.items():
        if k in doc:
            walk(doc[k], t, [k])
    for eid, e in doc.get('elements', {}).items():
        s = STRUCT_OF.get(e.get('category'))
        if s:
            walk(e, N(s), ['elements', eid])
    return out


