def sample(t, depth=0):
    k = t[0]
    if k in ('f64', 'f32'):
        return 1.5
    if k == 'bool':
        return True
    if k == 'str':
        return 's'
    if k == 'u':
        return 1
    if k == 'i':
        return -1
    if k == 'ref':
        return LEVEL_GUID
    if k == 'any':
        return 'x'
    if k in ('option', 'some'):
        return sample(t[1], depth)
    if k == 'vec':
        return [sample(t[1], depth)]
    if k == 'arr':
        return [sample(t[1], depth) for _ in range(t[2])]
    if k == 'tup':
        return [sample(x, depth) for x in t[1]]
    if k == 'map':
        return {'k': sample(t[1], depth)}
    if k == 'refmap':
        return {LEVEL_GUID: sample(t[1], depth)}
    if k == 'enummap':
        return {DEFS[t[1]]['variants'][0]['name']: sample(t[2], depth)}
    if k == 'named':
        d = DEFS[t[1]]
        if d['kind'] == 'struct':
            if d['tuple']:
                return [sample(f['ty'], depth) for f in d['fields']]
            if depth > 3:
                return {}
            return {f['name']: sample(f['ty'], depth + 1) for f in d['fields'] if not f['has_default']}
        if d['kind'] == 'enum':
            v = d['variants'][0]
            return {v['name']: sample(v['data'], depth)} if v['data'] else v['name']
        if d['kind'] == 'untagged':
            return sample(d['types'][0], depth)
        if d['kind'] == 'alias':
            return sample(d['ty'], depth)
        if d['kind'] == 'custom':
            return {'LibKind': 'wall', 'Colour': [1, 2, 3], 'Pen': 1, 'Weight': 1}.get(t[1], None)
    raise ValueError(t)


def positions(v, p):
    """Every place inside v (not v itself): paths."""
    if isinstance(v, list):
        for i, x in enumerate(v[:1]):
            yield p + [i]
            yield from positions(x, p + [i])
    elif isinstance(v, dict):
        for k, x in v.items():
            yield p + [k]
            yield from positions(x, p + [k])


def lists_and_maps(v, p):
    if isinstance(v, list):
        yield p, v
        for i, x in enumerate(v[:1]):
            yield from lists_and_maps(x, p + [i])
    elif isinstance(v, dict):
        yield p, v
        for k, x in v.items():
            yield from lists_and_maps(x, p + [k])


def getp(v, p):
    for k in p:
        v = v[k]
    return v


def setp(v, p, val):
    for k in p[:-1]:
        v = v[k]
    v[p[-1]] = val


def probes_for(t):
    out = [('top', x) for x in TOP]
    s = sample(t)
    out.append(('sample', s))
    for pos in positions(s, []):
        for pr in PROBES:
            x = copy.deepcopy(s)
            setp(x, pos, pr)
            out.append(('at %s' % '/'.join(map(str, pos)), x))
    for pos, node in lists_and_maps(s, []):
        if isinstance(node, list):
            if node:
                x = copy.deepcopy(s)
                n = getp(x, pos) if pos else x
                n.pop()
                out.append(('shorter %s' % '/'.join(map(str, pos)), x))
                x = copy.deepcopy(s)
                n = getp(x, pos) if pos else x
                n.append(copy.deepcopy(n[0]))
                out.append(('longer %s' % '/'.join(map(str, pos)), x))
        else:
            for k in list(node):
                x = copy.deepcopy(s)
                n = getp(x, pos) if pos else x
                del n[k]
                out.append(('without %s' % '/'.join(map(str, pos + [k])), x))
            x = copy.deepcopy(s)
            n = getp(x, pos) if pos else x
            n['zz_unknown'] = 1
            out.append(('unknown in %s' % '/'.join(map(str, pos)), x))
            for k in list(node)[:1]:
                for nk in ['zz', '00000000-0000-4000-8000-0000000000aa', '100000']:
                    x = copy.deepcopy(s)
                    n = getp(x, pos) if pos else x
                    n[nk] = n.pop(k)
                    out.append(('key %s at %s' % (nk, '/'.join(map(str, pos))), x))
    # unique by value
    seen = set()
    res = []
    for lab, x in out:
        key = json.dumps(x, sort_keys=True)
        if key not in seen:
            seen.add(key)
            res.append((lab, x))
    return res


