"""Sequences the original may keep as sets: each Vec field with two or more distinct items, reversed
(and with its first item repeated), opened and saved by both; the saved field compared."""
import sys, json, copy
from multiprocessing import Pool
sys.path.insert(0, '/tmp/loader-agent')
from lib import *
from dsl import DEFS, instances, MODEL

docs = {}
for f in ['c8', 'highrise', 'c3', 'house']:
    docs[f] = load('/tmp/loader-agent/corpus/%s.bimcraft' % f)


def getp(v, p):
    for k in p:
        v = v[k]
    return v


def vec_fields(t):
    return t[0] == 'vec' or (t[0] in ('option', 'some') and t[1][0] == 'vec')


jobs = []
done = set()
for fname, doc in docs.items():
    ins = instances(doc)
    # top-level vec sections (phases)
    for k, t in MODEL.items():
        if t[0] == 'vec' and k in doc and len(doc[k]) >= 2 and ('MODEL', k) not in done:
            done.add(('MODEL', k))
            jobs.append((fname, [], k))
    for sname, paths in ins.items():
        d = DEFS[sname]
        if d['tuple']:
            continue
        for f in d['fields']:
            if (sname, f['name']) in done or not vec_fields(f['ty']):
                continue
            for p in paths:
                inst = getp(doc, p)
                if not isinstance(inst, dict):
                    continue
                v = inst.get(f['name'])
                if isinstance(v, list) and len(v) >= 2 and len(set(json.dumps(x, sort_keys=True) for x in v)) == len(v):
                    done.add((sname, f['name']))
                    jobs.append((fname, p, f['name']))
                    break


def one(job):
    fname, p, k = job
    out = []
    for variant in ('reversed', 'dup'):
        res = []
        for exe in (ORIG, MINE):
            d = copy.deepcopy(docs[fname])
            inst = getp(d, p)
            if variant == 'reversed':
                inst[k] = list(reversed(inst[k]))
            else:
                inst[k] = inst[k] + [inst[k][0]]
            code, msg, saved = open_file(d, exe=exe, save=True)
            if code != 0:
                res.append('ERR ' + msg[:200])
                continue
            sd = json.loads(saved)
            try:
                res.append(norm(json.dumps(getp(sd, p).get(k))))
            except Exception as e:
                res.append('MISSING %r' % e)
        out.append((variant, res))
    return job, out


with Pool(8) as pool:
    for job, out in pool.imap_unordered(one, jobs):
        for variant, (o, m) in out:
            flag = 'same' if o == m else 'DIFF'
            print('%s %s %s %s %s' % (flag, job[0], '/'.join(map(str, job[1])), job[2], variant))
            if flag == 'DIFF':
                print('    O:', o[:300])
                print('    M:', m[:300])

