        if isinstance(v, (int, float)):
            out[k] = ([k], B)
        elif isinstance(v, str) and GUID.match(v):
            out[k] = ([k], G)
        elif isinstance(v, list) and v and isinstance(v[0], (int, float)) and not isinstance(v[0], bool):
            out[k] = ([k, 0], B)
        elif isinstance(v, list) and v and isinstance(v[0], list) and v[0] and isinstance(v[0][0], (int, float)):
            out[k] = ([k, 0, 0], B)
        elif isinstance(v, list) and v and isinstance(v[0], dict):
            # the first number inside the first item
            for kk, vv in v[0].items():
                if isinstance(vv, (int, float)) and not isinstance(vv, bool) and kk not in ('id', 'segment'):
                    out[k + '.' + kk] = ([k, 0, kk], B)
