                    }
                }
                Ok(())
            };
            if let Some(Value::Arr(rs)) = e.get("refs") {
                for r in rs {
                    point(r.get("at"))?;
                    if let Some(Value::Arr(ed)) = r.get("edge") {
                        for p in ed {
                            point(Some(p))?;
                        }
                    }
                }
            }
            point(e.get("at"))?;
            c.named("type", "dimension-type", "dimension type", "dimension_types", true)?;
        }
        "tag" => {
