def setp(d, p, val, delete=False):
    x = d
    for k in p[:-1]:
        x = x[k]
    if delete:
        if isinstance(x, dict):
            x.pop(p[-1], None)
        else:
            del x[p[-1]]
    else:
        x[p[-1]] = val


def pattern(p):
    """A path's shape: element ids by category, indices as #."""
    out = []
    for i, k in enumerate(p):
        if isinstance(k, int):
            out.append('#')
        elif i == 1 and p[0] == 'elements':
            out.append(DOC['elements'][k]['category'])
        elif len(p) > 1 and p[0] not in ('elements',) and i == 1:
            out.append('*')
        else:
            out.append(str(k))
    return '/'.join(out)


def mutations():
    muts = []
    roots = []
    only = set(args.only.split(',')) if args.only else None
    if not args.sections:
        for eid, e in DOC['elements'].items():
            if only and e['category'] not in only:
                continue
            roots.append(['elements', eid])
    else:
        for s in args.sections.split(','):
            if s in DOC:
                roots.append([s])
    seen = set()
    for r in roots:
        v = DOC
        for k in r:
            v = v[k]
        for p, x in paths(v, r, args.depth):
            pat = pattern(p)
            if len(p) > len(r):
                key = (pat, 'del')
                muts.append((p, 'del', None, pat))
            for name, val in PROBES:
                muts.append((p, name, val, pat))
            if isinstance(x, dict):
                muts.append((p + ['zz_unknown'], 'addkey', 1, pat + '/+'))
            if isinstance(x, str) and GUID.fullmatch(x):
                muts.append((p, 'upper', x.upper(), pat))
                muts.append((p, 'braces', '{' + x + '}', pat))
    if args.kinds:
        ks = set(args.kinds.split(','))
        muts = [m for m in muts if m[1] in ks]
    random.Random(args.seed).shuffle(muts)
    # one of each (pattern, kind) first, then the rest
    first, rest, seen = [], [], set()
    for m in muts:
        k = (m[3], m[1])
        if k in seen:
            rest.append(m)
        else:
            seen.add(k)
            first.append(m)
    muts = first + rest
    if args.max:
        muts = muts[:args.max]
    return muts


def strip_notes(s):
    lines = s.split('\n')
    if lines and lines[0].startswith('{'):
        try:
            r = json.loads(lines[0])
            r.pop('cads_not_reloaded', None)
            r.pop('links_not_loaded', None)
            lines[0] = json.dumps(r, sort_keys=True)
        except Exception:
            pass
    return '\n'.join(lines)


def one(m):
    p, kind, val, pat = m
    d = copy.deepcopy(DOC)
    try:
        if kind == 'del':
            setp(d, p, None, delete=True)
        else:
            setp(d, p, val)
    except Exception as e:
        return None
    text = json.dumps(d, indent=1)

