"""Every number of every element scaled (x0.5, x2, x-1, +0.5): where the original opens the file, mine
must too (and save it alike); where it refuses, what each says."""
import sys, json, copy
from multiprocessing import Pool
sys.path.insert(0, '/tmp/loader-agent')
from lib import *
DOC = load('/tmp/loader-agent/corpus/c8.bimcraft')
E = DOC['elements']


def leaves(v, p):
    if isinstance(v, bool):
        return
    if isinstance(v, (int, float)):
        yield p
    elif isinstance(v, dict):
        for k, x in v.items():
            if k in ('id',):
                continue
            yield from leaves(x, p + [k])
    elif isinstance(v, list):
        for i, x in enumerate(v[:3]):
            yield from leaves(x, p + [i])


jobs = []
for eid, e in E.items():
    for p in leaves(e, []):
        if p and p[0] == 'params':
            continue
        for f in ('half', 'double', 'neg', 'plus'):
            jobs.append((eid, p, f))
print(len(jobs), 'jobs', file=sys.stderr)


def one(job):
    eid, p, f = job
    res = []
    for exe in (ORIG, MINE):
        d = copy.deepcopy(DOC)
        x = d['elements'][eid]
        for k in p[:-1]:
            x = x[k]
        v = x[p[-1]]
        x[p[-1]] = {'half': v * 0.5, 'double': v * 2, 'neg': -v, 'plus': v + 0.5}[f]
        code, msg, saved = open_file(d, exe=exe, save=True)
        res.append((code, msg.replace('open: x.bimcraft: ', '')[:200], norm(saved) if saved else None))
    return job, res


bad = []
with Pool(8) as pool:
    for job, ((oc, om, osv), (mc, mm, msv)) in pool.imap_unordered(one, jobs, chunksize=8):
        if oc == 0 and mc != 0:
            bad.append(('MINE REFUSES', job, om, mm))
        elif oc == 0 and mc == 0 and osv != msv:
            bad.append(('SAVE', job, '', ''))
        elif oc != 0 and mc != 0 and om != mm and 'is not a BIMCraft project' in om + mm:
            bad.append(('NBP', job, om, mm))
print(len(bad), 'problems')
for kind, job, om, mm in bad[:60]:
    print(kind, E[job[0]]['category'], job[0], '/'.join(map(str, job[1])), job[2])
    if om or mm:
        print('    O:', om[:180])
        print('    M:', mm[:180])

