"""The library's rules on its ids and GUIDs: their order."""
import sys, json, copy
sys.path.insert(0, '/tmp/loader-agent')
from lib import *
d = load('/tmp/loader-agent/corpus/c8.bimcraft')
lib = d['library']
keys = sorted(lib, key=int)
k0, k1 = keys[0], keys[1]
grid = next(k for k, x in d['elements'].items() if x['category'] == 'grid')
G = d['elements'][grid]['guid']
cases = {}


def c(name):
    def deco(f):
        cases[name] = f
        return f
    return deco


@c('guid only')
def _(e):
    e['library'][k0]['guid'] = G


@c('second entry guid')
def _(e):
    e['library'][k1]['guid'] = G


@c('first low id, second guid')
def _(e):
    e['library'][k1]['guid'] = G
    e['library']['5000'] = e['library'].pop(k0)


@c('first guid, second low id')
def _(e):
    e['library'][k0]['guid'] = G
    e['library']['5000'] = e['library'].pop(k1)


@c('one entry: guid + low id')
def _(e):
    ent = e['library'].pop(k0)
    ent['guid'] = G
    e['library']['5000'] = ent


@c('one entry: guid + element id')
def _(e):
    ent = e['library'].pop(k0)
    ent['guid'] = G
    e['library']['100003'] = ent


@c('guid + id ref element')
def _(e):
    e['library'][k0]['guid'] = G
    e['elements']['100007']['level'] = 100000


@c('guid + element rule')
def _(e):
    e['library'][k0]['guid'] = G
    e['elements']['100187']['slope'] = 80


@c('guid uppercase')
def _(e):
    e['library'][k0]['guid'] = G.upper()


for name, f in cases.items():
