import sys, json, copy
from multiprocessing import Pool
sys.path.insert(0, '/tmp/loader-agent')
from lib import *
DOC = load(sys.argv[1])
E = DOC['elements']


def leaves(v, p):
    if isinstance(v, bool):
        return
    if isinstance(v, (int, float)):
        yield p
    elif isinstance(v, dict):
        for k, x in v.items():
            if k == 'id':
                continue
            yield from leaves(x, p + [k])
    elif isinstance(v, list):
        for i, x in enumerate(v[:2]):
            yield from leaves(x, p + [i])


jobs = []
seen = set()
for eid, e in E.items():
    for p in leaves(e, []):
        if p and p[0] == 'params':
            continue
        key = (e['category'], tuple(x if isinstance(x, str) else '#' for x in p))
        if key in seen:
            continue
        seen.add(key)
        jobs.append((eid, p))
print(len(jobs), 'jobs', file=sys.stderr)


def one(job):
